<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
/** Synthetic effective-switch reads never change protected stored settings; all HTTP is intercepted. */
final class GovernedGenerationMissingCeilingAcceptanceTest extends WP_UnitTestCase {
 private string $shop;private int $calls=0;private $http;private $settings;
 protected function setUp():void {
  parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));$this->shop='missing-ceiling-'.wp_rand();global $wpdb;$t=DigiForge\Database\Tables::class;$now=current_time('mysql',true);
  $wpdb->update($t::integrations(),['enabled'=>0],['provider'=>'ai']);self::assertSame(1,$wpdb->insert($t::integrations(),['provider'=>'ai','environment'=>'production','connection_key'=>'fixture-'.wp_generate_uuid4(),'display_name'=>'OFFLINE HTTP FIXTURE','status'=>'CONFIGURED','enabled'=>1,'config'=>'{}','created_at'=>$now,'updated_at'=>$now]));$id=(int)$wpdb->insert_id;self::assertSame(1,$wpdb->insert($t::integration_secrets(),['integration_id'=>$id,'secret_name'=>'api_key','ciphertext'=>DigiForge\Integrations\CredentialVault::encrypt('fixture',DigiForge\Integrations\Repository::secretContext($id,'api_key')),'fingerprint'=>'fixture','created_at'=>$now,'updated_at'=>$now]));
  $this->http=function($pre,$args){$this->calls++;$sent=json_decode($args['body'],true);return ['headers'=>[],'response'=>['code'=>200],'body'=>wp_json_encode(['id'=>'resp_'.str_replace('-','',wp_generate_uuid4()),'status'=>'completed','model'=>$sent['model'],'output_text'=>'{"fixture":true}','usage'=>['input_tokens'=>1,'output_tokens'=>1,'total_tokens'=>2]]),'cookies'=>[]];};add_filter('pre_http_request',$this->http,10,2);
  $this->settings=static function($sql)use($t){if(str_contains($sql,'SELECT setting_value, setting_type FROM '.$t::settings()))return str_contains($sql,"'stop_all'")?"SELECT 'false' AS setting_value, 'boolean' AS setting_type":"SELECT 'true' AS setting_value, 'boolean' AS setting_type";return $sql;};
 }
 protected function tearDown():void {remove_filter('query',$this->settings);remove_filter('pre_http_request',$this->http,10);parent::tearDown();}
 private function policy(?string $budget=null):void {$stages=[];foreach(['research','develop']as $stage){$stages[$stage]=['limit'=>10];if($budget!==null)$stages[$stage]['monthly_budget']=$budget;}self::assertNotWPError((new DigiForge\AI\ShopAiGovernanceRepository())->savePolicy(['shop_key'=>$this->shop,'currency'=>'USD','stages'=>$stages]));}
 public function testAllActualPublicFacadesDenyAbsentReviewedMonetaryCeilingBeforeReservationOrHttp():void {
  $this->policy();add_filter('query',$this->settings);$g=new DigiForge\AI\GovernedGeneration();try{foreach([fn()=>$g->develop($this->shop,'develop','fixture','missing-develop'),fn()=>$g->research($this->shop,'fixture','missing-research'),fn()=>$g->startBackgroundDevelop($this->shop,'develop','fixture','missing-background')]as $call){$result=$call();self::assertWPError($result);self::assertSame('ai_generation_budget_missing',$result->get_error_code());}}finally{remove_filter('query',$this->settings);}
  self::assertSame(0,$this->calls);$this->assertProtectedAndUnused();
 }
 public function testExplicitZeroCeilingCannotAuthorizePositiveReviewedProviderQuote():void {
  $this->policy('0');$contract=DigiForge\Launch\OpenAIClient::generationContract('fixture',8000);$quote=['provider'=>'openai','quote_id'=>'zero-denied-'.wp_generate_uuid4(),'model'=>$contract['model'],'request_sha256'=>$contract['request_sha256'],'currency'=>'USD','maximum_charge'=>'0.1','inclusive_all_charges'=>true,'valid_from'=>gmdate('Y-m-d\TH:i:s\Z',time()-60),'valid_until'=>gmdate('Y-m-d\TH:i:s\Z',time()+600)];self::assertNotWPError((new DigiForge\AI\MonetaryReservationRepository())->reviewQuote($this->shop,(string)wp_json_encode($quote),'CONFIRM_PROVIDER_QUOTE'));add_filter('query',$this->settings);
  try{$result=(new DigiForge\AI\GovernedGeneration())->develop($this->shop,'develop','fixture','zero-denied');}finally{remove_filter('query',$this->settings);}
  self::assertWPError($result);self::assertSame('ai_money_workflow_budget_ceiling',$result->get_error_code());self::assertSame(0,$this->calls);$this->assertProtectedAndUnused();
 }
 public function testActualControlledProbeActionCannotBypassMissingReviewedMonetaryScope():void {
  ShopAccessFixture::reset();ShopAccessFixture::authorizeActor(get_current_user_id(),DigiForge\Security\ShopAccessPolicy::canonicalShops(),['manage_digiforge_automation']);
  $action='digiforge_frontend_controlled_ai_test';$body=['action'=>$action,'_wpnonce'=>wp_create_nonce($action)];$post=$_POST;$request=$_REQUEST;$redirect='';$capture=static function($url)use(&$redirect):never{$redirect=$url;throw new RuntimeException('offline-controlled-probe-redirect');};$switches=static function($sql){if(str_contains($sql,'SELECT setting_value, setting_type FROM '.DigiForge\Database\Tables::settings()))return str_contains($sql,"'stop_all'")||str_contains($sql,"'product_development'")?"SELECT 'false' AS setting_value, 'boolean' AS setting_type":"SELECT 'true' AS setting_value, 'boolean' AS setting_type";return $sql;};add_filter('query',$switches);add_filter('wp_redirect',$capture);
  try{$_POST=$_REQUEST=$body;try{(new DigiForge\Portal\FrontendControls())->controlledAiTest();self::fail('Controlled probe must return to the operator.');}catch(RuntimeException $e){self::assertSame('offline-controlled-probe-redirect',$e->getMessage());}}finally{$_POST=$post;$_REQUEST=$request;remove_filter('query',$switches);remove_filter('wp_redirect',$capture);}
  self::assertSame(0,$this->calls);parse_str((string)parse_url($redirect,PHP_URL_QUERY),$query);self::assertSame('1',$query['df_error']);self::assertStringContainsString('monetary',$query['df_message']);self::assertStringContainsString('quote',$query['df_message']);$this->assertProtectedAndUnused();
 }
 private function assertProtectedAndUnused():void {global $wpdb;self::assertSame('0',(string)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DigiForge\Database\Tables::shop_ai_usage().' WHERE shop_key=%s',$this->shop)));self::assertTrue(DigiForge\Core\Settings::safety_locked());self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertFalse(DigiForge\Core\Settings::get('automation_armed',false));}
}
